const RAW_COMMERCE_LAYER_ENTRY = RAW_COMPOSIO_COMMERCE_ENTRIES.find((entry) => entry.id === 'commerce-layer');
if (!RAW_COMMERCE_LAYER_ENTRY?.icon_svg) throw new Error('Missing Commerce Layer brand artwork');

/** Reused by the local direct connector so the reviewed real brand asset remains unchanged. */
export const COMMERCE_LAYER_ICON_SVG = renderableSvg(RAW_COMMERCE_LAYER_ENTRY.icon_svg);

export const COMPOSIO_COMMERCE_ENTRIES: CatalogEntry[] = RAW_COMPOSIO_COMMERCE_ENTRIES
  .filter((entry) => entry.id !== 'commerce-layer')
  .map(
  (entry) => {
    const source = COMPOSIO_COMMERCE_ICON_SOURCES[entry.id];
    if (!source) throw new Error(`Missing icon provenance for commerce connector: ${entry.id}`);
    return {
      ...entry,
      icon_svg: entry.id === 'redcircle-api'
        ? REDCIRCLE_API_ICON_SVG
        : renderableSvg(entry.icon_svg || ''),
      icon_source_url: source.url,
      icon_source_sha256: source.sha256,
    };
  },
);
